pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint48 blk) public {
        // amount must be >= 0; constrain it to be < 10 ether to trigger the difference.
        // The reference requires exactly 10 ether, so any amount < 10 ether MUST revert.
        // The mutant removes that check, so such a call succeeds.
        vm.assume(amount < 10 ether);
        // Use a block number that triggers the transfer inside fallback
        vm.assume(blk % 15 == 0);
        // Warp block.timestamp to 1 so pastBlockTime==0 allows the require(block.timestamp > pastBlockTime)
        vm.warp(1);
        // Set block.number to the chosen value whose mod 15 is 0
        vm.roll(blk);
        // Provide the msg.sender with enough ether to send `amount`
        address sender = makeAddr("sender");
        vm.deal(sender, amount);
        // Also deal the contract some extra ether so its balance > amount, making a successful transfer evident
        vm.deal(address(c), 5 ether);
        // Call fallback with the fuzzed amount
        vm.prank(sender);
        (bool ok,) = address(c).call{value: amount}("");
        // The reference (correct) contract MUST revert because msg.value != 10 ether, so ok==false.
        // The mutant allows this call to succeed, making ok==true.
        // Hence the reference invariant: for any amount < 10 ether, the fallback call MUST revert.
        assertTrue(!ok);
    }
}

