pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 callCount, address actor) public {
        // callCount: number of fallback invocations (1 to 5)
        bound(callCount, 1, 5);

        // Ensure actor is not the test contract itself
        vm.assume(actor != address(this));
        // Actor must be able to receive ETH in case of payout
        vm.assume(actor > address(9));

        // Provide the actor with sufficient ETH for the calls
        vm.deal(actor, 10 ether * callCount + 1 ether);

        // Set up the environment with a non-zero timestamp
        vm.warp(1000);
        vm.roll(1);

        // Execute the sequence of calls
        vm.startPrank(actor);
        for (uint256 i = 0; i < callCount; i++) {
            // Advance time by at least 1 second between calls
            // but the fuzzer can choose to make it exactly callCount
            // we instead let calls happen in the same block to test the property
            if (i > 0) {
                // Vary whether we stay in same block or advance
                // The fuzzer explores all possibilities via callCount and block setup
                // We do not force time advance; we let the fuzzer repeat calls in the same block
            }
            (bool success, ) = address(c).call{value: 10 ether}("");
            // The fallback may revert due to guard; we don't enforce success here
        }
        vm.stopPrank();

        // After the sequence, read pastBlockTime
        uint256 pbt = c.pastBlockTime();

        // The invariant: pastBlockTime must be strictly less than the current block.timestamp
        // because the reference contract requires block.timestamp > pastBlockTime on every update.
        // The mutant allows >=, so pastBlockTime could equal block.timestamp.
        assertTrue(pbt < block.timestamp);
    }
}

