pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, uint8 numCalls) public {
        // numCalls controls how many re-entrant calls we make in the same block to try to drain the contract.
        // We bound it to a reasonable range to keep the fuzzer efficient.
        uint256 calls = bound(numCalls, 1, 20);
        // seed influences the block number. We assume a block where the transfer is NOT triggered.
        // We use vm.roll to set a block number that never triggers the transfer (i.e., not divisible by 15).
        // A block number that is never divisible by 15 is e.g., a multiple of 5 + 1. We can just set block number to 1.
        // Actually, we need the attacker to be able to repeatedly call fallback without the transfer being triggered.
        // Transfer triggers when block.number % 15 == 0. So we set block.number to a value that is not divisible by 15.
        uint256 blockNum = 1; // 1 % 15 != 0, transfer never happens.
        vm.roll(blockNum);

        // Deploy an attacker contract that will re-enter into c.fallback() multiple times in the same block.
        Attacker attacker = new Attacker(c);
        // Fund the attacker with enough ETH to send 10 ether multiple times.
        vm.deal(address(attacker), calls * 10 ether + 1 ether);

        // Record the initial balance of c.
        uint256 initialBalance = address(c).balance;

        // The attacker starts the re-entrant loop.
        attacker.attack{value: 10 ether}(calls);

        // After all calls, the balance of c should have increased by exactly the amount of ether sent by the attacker
        // that was not paid out (since transfer never triggered). The attacker sent calls * 10 ether.
        // In the correct contract (strict >), the re-entrant loop is not possible because pastBlockTime is updated
        // to current block.timestamp on the first call, and subsequent calls in the same block fail the require(block.timestamp > pastBlockTime).
        // Thus the attacker only successfully executes the first call, and subsequent calls revert.
        // The balance of c should be initialBalance + 10 ether.
        // In the buggy contract (>=), the attacker can re-enter successfully multiple times, sending 10 ether each time.
        // Since no transfer happens, the contract's balance becomes initialBalance + calls * 10 ether.
        // The difference: initialBalance + 10 ether vs initialBalance + calls * 10 ether.
        // We assert that the contract balance is EXACTLY initialBalance + 10 ether, which holds for the reference
        // but fails for the bug.
        assertEq(address(c).balance, initialBalance + 10 ether, "only first call should succeed");
    }
}

contract Attacker {
    C public target;
    uint256 private callsRemaining;
    bool private firstCall;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 _calls) external payable {
        require(msg.value == 10 ether, "attack must be funded with 10 ether");
        callsRemaining = _calls - 1;
        firstCall = true;
        // Make the first call to trigger the fallback.
        // The fallback will call back into this contract via transfer? No, transfer only happens on modulo 15.
        // We need to explicitly call back from the fallback into the attacker's receive function.
        // But C's fallback does NOT call back into the sender; it only does a transfer if condition is met.
        // We need a re-entrant exploit where the attacker's fallback/receive calls back into C.
        // However, C's fallback does not make an external call to msg.sender unless the transfer condition is met.
        // Since we avoid the transfer condition, there is no automatic re-entrancy.
        // To trigger the bug, we need an exploitable pattern that arises from the difference in the require check.
        // The previous attempts specifically mentioned re-entrant loops, but without an external call inside C,
        // how does the re-entrancy happen?
        // The difference is: P requires strictly >, M requires >=.
        // In P, you cannot call fallback twice in the same block because after first call, pastBlockTime = block.timestamp,
        // and the next call will require block.timestamp > block.timestamp, which is false.
        // In M, you can call fallback any number of times in the same block without reverting (as long as other requires pass).
        // So the bug is that you can successfully execute fallback multiple times in the same block.
        // To demonstrate this via a re-entrant attack, we need a way for the attacker to make multiple calls to fallback
        // within a single transaction. Since Ethereum transactions are atomic, we can just do a loop.
        // There's no need for a separate attacker contract that uses receive; we can just prank as the attacker and call
        // fallback multiple times.
        // However, the test must be fuzzed. The fuzzer can supply a number of calls.
        // The earlier try that used a loop in the test was rejected? No, the instruction says "These approaches were already tried for this difference; do not repeat them:" listing two approaches that both focus on pastBlockTime being strictly less. Those are not the same as a loop.
        // But the spec also says: "You MAY use vm.deal, vm.prank, vm.startPrank, vm.stopPrank, vm.warp, vm.roll ..."
        // So we can just loop and call c.fallback multiple times with 10 ether.
        // No need for Attacker contract with re-entrant receive.

        // However, the requirement says: "ADVERSARIAL COUNTERPARTY: if the difference only manifests through the BEHAVIOUR OF AN EXTERNAL PARTY ... you MUST DEPLOY a minimal helper contract that embodies the adversarial behaviour ..."
        // Is the difference manifested through the behaviour of an external party? The difference is that multiple calls to fallback succeed. That's not about the behavior of an external party failing or re-entering; it's about the contract's own state logic. So an adversarial helper is NOT required.
        // But we already wrote an Attacker. Let's simplify to just a loop.
        // Let's rewrite the test without the Attacker contract, just using a loop.
        // But wait, a loop might not be "adversarial counterparty" but it's just the test logic. The test function can contain a for loop.
        // The previous compile error was because of `target.fallback{value: 10 ether}()`; in Solidity, `fallback` is a reserved keyword and cannot be called by name. You must use a low-level call: `address(target).call{value: 10 ether}("")` or define a function that triggers fallback.
        // Since C has no receive function, only fallback, sending a call with empty data triggers fallback.
        // So we use `(bool success,) = address(c).call{value: 10 ether}("");`
        // That's the proper way.

        // Let's adjust the code.
    }
}

