pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 calls, uint256 blockNum, uint256 timestamp) public {
        // Restrict calls to at least 2 to trigger potential multiple invocations
        calls = bound(calls, 2, 10);
        // Set block number such that block.number % 15 != 0 to avoid balance drain
        blockNum = bound(blockNum, 1, type(uint256).max);
        if (blockNum % 15 == 0) {
            blockNum += 1;
        }
        // Set a sufficiently large base timestamp
        timestamp = bound(timestamp, 1000, type(uint256).max - calls);

        // Setup account with enough ether
        address actor = address(0x100);
        vm.deal(actor, 100 ether);

        // Warp to initial timestamp
        vm.warp(timestamp);
        // Set block number
        vm.roll(blockNum);

        // Execute calls within the same block
        vm.startPrank(actor);
        for (uint256 i = 0; i < calls; i++) {
            (bool success, ) = address(c).call{value: 10 ether}("");
            require(success, "call failed");
            // Warp time forward by 1 to stay within valid timestamp range but ensure sequential calls are possible
            vm.warp(timestamp + i);
        }
        vm.stopPrank();

        // After all calls, pastBlockTime must equal the timestamp of the last block
        assertEq(c.pastBlockTime(), block.timestamp);
    }
}

