    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 blockNumber, uint256 timestamp) public {
        // 1. Admissible domain: pastBlockTime starts 0, so we need timestamp > 0 (any positive safe to assume)
        vm.assume(timestamp > 0);

        // 2. Set block conditions: need block.number % 15 == 0 to trigger the transfer
        uint256 baseBlock = (blockNumber / 15) * 15;
        vm.roll(baseBlock);
        vm.warp(timestamp);

        // Fund the caller with the required 10 ether
        address caller = address(0xBEEF);
        vm.deal(caller, 10 ether);
        vm.prank(caller);

        // Due to potential revert on transfer to address(0), use try/catch to observe behavior
        bool ok;
        try c.fallback{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
