pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fuzz_blocks, uint256 fuzz_timestamp) public {
        // Restrict the fuzzed domain to admissible values.
        // fuzz_blocks determines how many times we call fallback, bounded to [1, 100] to keep runtime reasonable
        // but wide enough to trigger the bug.
        uint256 nCalls = bound(fuzz_blocks, 1, 100);
        // fuzz_timestamp determines the starting timestamp. Ensure future timestamps are > 0.
        uint256 startTime = bound(fuzz_timestamp, 1, type(uint64).max);

        // Set up caller with enough Ether: 10 ether per call.
        address caller = makeAddr("caller");
        vm.deal(caller, 10 ether * nCalls);

        // Warp to a known starting timestamp and block number.
        vm.warp(startTime);
        vm.roll(1);

        vm.startPrank(caller);
        // Perform nCalls calls to fallback. After the first call, the reference updates pastBlockTime;
        // the mutant does not, so eventual timestamp requirements will fail.
        for (uint256 i = 0; i < nCalls; i++) {
            // We must call on a new block each time to avoid timestamp == pastBlockTime.
            // Advance timestamp and block.
            vm.warp(startTime + 1 + i);
            vm.roll(1 + i + 1);
            (bool ok,) = address(c).call{value: 10 ether}("");
            // We allow failure in the loop; the property will check that if a call succeeds, the invariant holds.
            // But we need to know if the last call succeeded or failed.
            if (i == nCalls - 1) {
                // We will assess the property based on this last call's success.
                bool lastCallOk = ok;
                vm.stopPrank();
                // After the last call, if it succeeded (no revert), the invariant must hold:
                // block.timestamp == c.pastBlockTime().
                if (lastCallOk) {
                    assertTrue(block.timestamp == c.pastBlockTime());
                } else {
                    // If the call reverted, it's fine; the invariant is vacuously true for reverted calls.
                    // Do nothing; the assert should pass.
                    assertTrue(true);
                }
                return;
            }
        }
        vm.stopPrank();
        // Should not reach here.
    }
}
